eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   PROJECTS: () => (/* binding */ PROJECTS)\n/* harmony export */ });\nconst PROJECTS = {\n    brucedavidson: {\n        name: \"Bruce Davidson Productions\",\n        tagline: \"Ebook web app with integrated payments.\",\n        blurb: \"A bespoke platform for an American client to sell and distribute their ebooks securely. Integrated with PayPal for seamless checkout.\",\n        role: \"Full-stack developer\",\n        domain: \"brucedavidsonproductions.com\",\n        link: \"https://www.brucedavidsonproductions.com/\",\n        image: \"/images/brucedavidson.jpg\",\n        year: \"2026\",\n        stack: [\n            \"Next.js\",\n            \"Prisma\",\n            \"NeonDB\",\n            \"NextAuth\",\n            \"PayPal\"\n        ],\n        metrics: [\n            [\n                \"type\",\n                \"ebook app\"\n            ],\n            [\n                \"auth\",\n                \"NextAuth\"\n            ],\n            [\n                \"payments\",\n                \"PayPal\"\n            ],\n            [\n                \"db\",\n                \"NeonDB\"\n            ]\n        ],\n        context: \"The American client needed a custom, branded platform to distribute their ebooks directly to customers without relying on third-party marketplaces.\",\n        approach: [\n            \"Next.js App Router for fast page loads and solid SEO.\",\n            \"NeonDB and Prisma to provide a resilient, type-safe data layer.\",\n            \"NextAuth for secure session management and PayPal for immediate checkout.\"\n        ],\n        tradeoffs: [\n            \"Opted for NextAuth over managed identity providers to retain full control over the user data and authentication flow.\"\n        ],\n        arch: [\n            \"Next.js client\",\n            \"NextAuth API\",\n            \"Prisma ORM\",\n            \"NeonDB\",\n            \"PayPal\"\n        ]\n    },\n    neuroscan: {\n        name: \"NeuroScan AI\",\n        tagline: \"Brain tumor MRI classifier with diagnostic-grade accuracy.\",\n        blurb: \"A Nextjs + Python web app that classifies brain MRI scans into four tumor categories. Optimized to run real-time inference on CPU-only cloud infrastructure — no GPU dependency, no per-request cost spike.\",\n        role: \"Full-stack engineer + ML pipeline\",\n        domain: \"brain-tumor-web-smiu.vercel.app\",\n        link: \"https://brain-tumor-web-smiu.vercel.app/\",\n        image: \"/images/braintumor.jpg\",\n        year: \"2026\",\n        stack: [\n            \"Nextjs\",\n            \"Python\",\n            \"TensorFlow\",\n            \"FastAPI\",\n            \"Vercel\"\n        ],\n        metrics: [\n            [\n                \"classification accuracy\",\n                \"95%\"\n            ],\n            [\n                \"p95 inference\",\n                \"3.8s\"\n            ],\n            [\n                \"infrastructure\",\n                \"CPU-only\"\n            ],\n            [\n                \"tumor classes\",\n                \"4-way\"\n            ]\n        ],\n        context: \"Radiologists at smaller hospitals don't have access to deep-learning triage tools — the models exist in research papers, but the path from notebook to a real product nobody has built. The constraint was practical: any system has to run on commodity cloud without GPU budget.\",\n        approach: [\n            \"Picked a 4-class architecture over binary so the model degrades gracefully on edge cases instead of confidently misclassifying.\",\n            \"Stripped TensorFlow ops down to what CPU inference can do efficiently — quantized weights, batched preprocessing in NumPy.\",\n            \"Treated the <4s latency target as a hard contract: the system fails loudly if it can't hit it, instead of silently degrading.\"\n        ],\n        tradeoffs: [\n            \"No GPU = simpler infra but a ceiling on model size. Picked accuracy over experimentation.\",\n            \"No DICOM viewer — out of scope; the goal was triage, not full reading workflow.\"\n        ],\n        arch: [\n            \"Next.js client\",\n            \"FastAPI router\",\n            \"TF inference worker\",\n            \"S3 image cache\"\n        ]\n    },\n    gmr: {\n        name: \"Global Music Rater\",\n        tagline: \"Full-stack music marketplace with in-browser audio tooling.\",\n        blurb: \"A marketplace where artists upload tracks, get rated, and earn revenue. Direct-to-storage uploads bypass the server entirely; the clipping engine runs in the browser.\",\n        role: \"Full-stack engineer\",\n        domain: \"globalmusicrater.com\",\n        link: \"https://www.globalmusicrater.com/\",\n        image: \"/images/globalmusicrater.jpg\",\n        year: \"2026\",\n        stack: [\n            \"Nextjs\",\n            \"Node\",\n            \"Express\",\n            \"MongoDB\",\n            \"AWS S3\",\n            \"Stripe\"\n        ],\n        metrics: [\n            [\n                \"upload pipeline\",\n                \"direct-to-S3\"\n            ],\n            [\n                \"clip engine\",\n                \"in-browser\"\n            ],\n            [\n                \"payouts\",\n                \"automated\"\n            ],\n            [\n                \"stack\",\n                \"Nextjs\",\n                \"\"\n            ]\n        ],\n        context: \"Existing music platforms either lock artists into bad revenue terms or require ops-heavy admin work. The product brief was: let an artist upload, sample, and earn — without the platform touching the audio bytes more than necessary.\",\n        approach: [\n            \"Presigned-URL uploads — clients hit S3 directly so the API never proxies multi-MB audio.\",\n            \"Built the clipping UX on the Web Audio API; offload chops are free to the platform.\",\n            \"Stripe Connect for payouts with idempotent webhooks driving revenue ledger updates.\"\n        ],\n        tradeoffs: [\n            \"In-browser clipping means worse experience on weak devices — accepted; the desktop-first audience justified it.\"\n        ],\n        arch: [\n            \"React client\",\n            \"Express API\",\n            \"S3 presigned\",\n            \"Stripe webhooks\",\n            \"MongoDB\"\n        ]\n    },\n    gym: {\n        name: \"ProCheckGym\",\n        tagline: \"Multi-tenant gym management SaaS with automated enforcement.\",\n        blurb: \"A platform that runs the back-office for gyms — members, attendance, subscriptions, billing — with cron-driven enforcement that keeps the data honest without staff intervention.\",\n        role: \"Backend lead\",\n        domain: \"procheckgym.com\",\n        link: \"https://www.procheckgym.com/\",\n        image: \"/images/procheckgym.jpg\",\n        year: \"2026\",\n        stack: [\n            \"ExpressJs\",\n            \"MongoDB\",\n            \"Neondb\",\n            \"Nextjs\",\n            \"Cron\",\n            \"Docker\"\n        ],\n        metrics: [\n            [\n                \"modules\",\n                \"6\"\n            ],\n            [\n                \"cron jobs\",\n                \"4\"\n            ],\n            [\n                \"tenancy\",\n                \"multi-tenant\"\n            ],\n            [\n                \"uptime\",\n                \"99.9%\"\n            ]\n        ],\n        context: \"Gym staff don't want to be data janitors. The pattern across every gym I talked to was the same: members lapse, attendance gets fuzzy, and someone has to spend Fridays cleaning the database.\",\n        approach: [\n            \"Modular NestJS — every domain (members, attendance, subscriptions) is its own bounded context.\",\n            \"Cron workers run nightly: expire stale subscriptions, reconcile attendance gaps, send renewal nudges.\",\n            \"Tenant isolation at the data layer — one shared cluster, deterministic per-gym indexing.\"\n        ],\n        tradeoffs: [\n            \"Single Mongo cluster vs per-tenant — cheaper to run, but the day a gym needs data sovereignty I rebuild.\"\n        ],\n        arch: [\n            \"React admin\",\n            \"NestJS gateway\",\n            \"Auth module\",\n            \"Members svc\",\n            \"Cron worker\",\n            \"MongoDB\"\n        ]\n    },\n    asan: {\n        name: \"AsanKarobar\",\n        tagline: \"POS, inventory and invoicing SaaS for retail operations.\",\n        blurb: \"A multi-tenant SaaS managing point-of-sale, inventory, vendor relationships and invoicing for retailers. Built API-first so the same backend powers POS terminals, admin web, and (eventually) mobile.\",\n        role: \"Backend architect\",\n        domain: \"asankarobar.biz\",\n        link: \"https://www.asankarobar.biz/\",\n        image: \"/images/asankarobar.jpg\",\n        year: \"2025\",\n        stack: [\n            \"NestJS\",\n            \"MongoDB\",\n            \"REST\",\n            \"Docker\"\n        ],\n        metrics: [\n            [\n                \"domains\",\n                \"POS · INV · AP\"\n            ],\n            [\n                \"tenancy\",\n                \"multi-tenant\"\n            ],\n            [\n                \"throughput\",\n                \"optimized\"\n            ],\n            [\n                \"db\",\n                \"sharded\"\n            ]\n        ],\n        context: \"Mid-market retail in Pakistan runs on spreadsheets and WhatsApp. Existing SaaS is either localized but ancient, or modern but priced for the US market.\",\n        approach: [\n            \"Domain-driven module split: POS, Inventory, Vendor, Invoice — each owns its data, communicates via the gateway.\",\n            \"Read-optimized denormalization for hot tables; write path stays normalized for correctness.\",\n            \"Built the invoice engine first — every other module hangs off the financial truth.\"\n        ],\n        tradeoffs: [\n            \"No real-time sync between POS terminals yet. Eventually consistent; queued conflict resolution.\"\n        ],\n        arch: [\n            \"React POS\",\n            \"NestJS gateway\",\n            \"Inventory svc\",\n            \"Vendor svc\",\n            \"Invoice svc\",\n            \"MongoDB\"\n        ]\n    },\n    edtech: {\n        name: \"OnlineTeacher1to1\",\n        tagline: \"Live tutoring platform — student & teacher dashboards from scratch.\",\n        blurb: \"A live 1-to-1 tutoring frontend built end-to-end: student onboarding, teacher dashboards, scheduling, payment flows. Production-ready and responsive across devices.\",\n        role: \"Frontend lead\",\n        domain: \"onlineteachers1to1.com\",\n        link: \"https://onlineteachers1to1.com/\",\n        year: \"2025\",\n        stack: [\n            \"Next.js\",\n            \"shadcn/ui\",\n            \"Tailwind\",\n            \"REST APIs\"\n        ],\n        metrics: [\n            [\n                \"surfaces\",\n                \"2 dashboards\"\n            ],\n            [\n                \"payments\",\n                \"integrated\"\n            ],\n            [\n                \"responsive\",\n                \"mobile-first\"\n            ],\n            [\n                \"scope\",\n                \"built from scratch\"\n            ]\n        ],\n        context: \"A tutoring platform without a usable interface is just a phone number. The brief was to take backend endpoints and turn them into two coherent experiences — one for students, one for teachers — that didn't feel like two different products.\",\n        approach: [\n            \"shadcn/ui as the foundation, then layered custom components only where the brand needed it.\",\n            \"Shared component library across the two dashboards — same building blocks, different compositions.\",\n            \"Mobile responsiveness as a first-class constraint, not a final-week scramble.\"\n        ],\n        tradeoffs: [\n            \"Used shadcn defaults heavily — fast to ship, harder to differentiate visually until later.\"\n        ],\n        arch: [\n            \"Next.js student app\",\n            \"Next.js teacher app\",\n            \"Auth\",\n            \"Scheduler API\",\n            \"Payment gateway\"\n        ]\n    },\n    attendance: {\n        name: \"Attendyfy\",\n        tagline: \"Biometric attendance pipeline at Bright Solutions — backend.\",\n        blurb: \"A backend that handles thousands of daily check-ins from ZKBioTime biometric devices. Solved a hairy connectivity problem with secure tunneling so remote devices talk to the local server without firewall gymnastics.\",\n        role: \"Backend developer\",\n        domain: \"internal · bright solutions\",\n        link: \"https://www.attendyfy.com/\",\n        image: \"/images/attendyfy.jpg\",\n        year: \"2025\",\n        stack: [\n            \"Expressjs\",\n            \"MongoDB\",\n            \"Neondb\",\n            \"Ngrok\",\n            \"ZKBioTime\",\n            \"Hikvision\",\n            \"\"\n        ],\n        metrics: [\n            [\n                \"daily check-ins\",\n                \"thousands\"\n            ],\n            [\n                \"data accuracy\",\n                \"100%\"\n            ],\n            [\n                \"tunneling\",\n                \"Ngrok\"\n            ],\n            [\n                \"validation\",\n                \"strict schema\"\n            ]\n        ],\n        context: \"Biometric hardware in the field, backend in a private network, firewall rules between them. The classic enterprise headache that usually ends in a VPN reconfig and a sad sysadmin.\",\n        approach: [\n            \"Ngrok secure tunneling for device-to-backend traffic — bypasses firewall reconfig entirely.\",\n            \"Strict validation at every API boundary — biometric data is messy, the backend assumes nothing.\",\n            \"Modular Mongo schema designed to scale across thousands of daily records without index pain.\"\n        ],\n        tradeoffs: [\n            \"Ngrok dependency is a vendor risk — long-term, plan to migrate to a self-hosted tunnel.\"\n        ],\n        arch: [\n            \"ZKBioTime device\",\n            \"Ngrok tunnel\",\n            \"NestJS API\",\n            \"Validation pipe\",\n            \"MongoDB\"\n        ]\n    },\n    recipe: {\n        name: \"Recipe App\",\n        tagline: \"A weekend React app that taught me Firebase.\",\n        blurb: \"Built a responsive recipe app with search, filters and real-time data updates. Small project, mostly a vehicle to learn Firebase fluency.\",\n        role: \"Solo build\",\n        domain: \"perfect-recipe-orcin.vercel.app\",\n        link: \"https://perfect-recipe-orcin.vercel.app/\",\n        image: \"/images/reciper.jpg\",\n        year: \"2024\",\n        stack: [\n            \"React\",\n            \"Firebase\"\n        ],\n        metrics: [\n            [\n                \"features\",\n                \"search · filter\"\n            ],\n            [\n                \"data\",\n                \"real-time\"\n            ],\n            [\n                \"scope\",\n                \"weekend\"\n            ],\n            [\n                \"goal\",\n                \"learn firebase\"\n            ]\n        ],\n        context: \"Sometimes you build a thing to learn another thing. Real-time data was the lesson; recipes were the excuse.\",\n        approach: [\n            \"Firebase Realtime Database for live updates without writing a backend.\",\n            \"Search and filter as derived state from the live store.\"\n        ],\n        tradeoffs: [\n            \"Firebase locks you in. Fine for a learning project; would not start a SaaS here today.\"\n        ],\n        arch: [\n            \"React app\",\n            \"Firebase RTDB\"\n        ]\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/projects.js\n");

